// ===== src/00-event-bus.js =====
/* MasseBot 2 - EventBus */
class MB2EventBus {
  constructor(diagnostics) {
    this._listeners = new Map();
    this._diag = diagnostics || null;
  }
  on(name, fn) {
    if (typeof fn !== "function") throw new TypeError("listener must be a function");
    if (!this._listeners.has(name)) this._listeners.set(name, new Set());
    this._listeners.get(name).add(fn);
    return () => this.off(name, fn);
  }
  once(name, fn) {
    const off = this.on(name, (...args) => { off(); fn(...args); });
    return off;
  }
  off(name, fn) {
    const set = this._listeners.get(name);
    if (!set) return false;
    const ok = set.delete(fn);
    if (set.size === 0) this._listeners.delete(name);
    return ok;
  }
  emit(name, payload) {
    const set = this._listeners.get(name);
    if (!set || set.size === 0) return 0;
    let n = 0;
    [...set].forEach(fn => {
      try { fn(payload); n++; }
      catch (err) {
        if (this._diag) this._diag.error("event-listener", { event: name, error: String(err && err.stack || err) });
      }
    });
    return n;
  }
  clear() { this._listeners.clear(); }
  listenerCount(name) { return this._listeners.has(name) ? this._listeners.get(name).size : 0; }
  snapshot() {
    const byEvent={};let total=0;
    for(const [name,set] of this._listeners.entries()){const n=set.size;byEvent[name]=n;total+=n;}
    return{total,eventTypes:this._listeners.size,byEvent};
  }
}

// ===== src/01-diagnostics.js =====
/* MasseBot 2 - Diagnostics */
class MB2Diagnostics {
  constructor(limit = 500) {
    this.limit = Math.max(50, Number(limit) || 500);
    this.entries = [];
  }
  _push(level, topic, data) {
    const row = { ts: Date.now(), level, topic, data: data === undefined ? null : data };
    this.entries.push(row);
    if (this.entries.length > this.limit) this.entries.splice(0, this.entries.length - this.limit);
    return row;
  }
  debug(topic, data) { return this._push("debug", topic, data); }
  info(topic, data) { return this._push("info", topic, data); }
  warn(topic, data) { return this._push("warn", topic, data); }
  error(topic, data) { return this._push("error", topic, data); }
  recent(count = 50) { return this.entries.slice(-Math.max(1, count)); }
  clear() { this.entries.length = 0; }
  snapshot() { return this.entries.slice(); }
}

// ===== src/01a-clock.js =====
/* MasseBot 2 - owned runtime clock / async lifecycle */
class MB2Clock {
  constructor(diagnostics = null, name = "instance") {
    this.diag = diagnostics || null;
    this.name = String(name || "instance");
    this._entries = new Map();
    this._seq = 0;
    this._destroyed = false;
  }
  _schedule(type, fn, ms, owner = "anonymous", onCancel = null) {
    if (this._destroyed) return null;
    if (typeof fn !== "function") throw new TypeError("clock callback must be a function");
    const token = ++this._seq;
    const delay = Math.max(0, Number(ms) || 0);
    const entry = {
      token, type, owner:String(owner || "anonymous"), delay, createdAt:Date.now(),
      native:null, onCancel:typeof onCancel === "function" ? onCancel : null
    };
    const invoke = () => {
      const current = this._entries.get(token);
      if (!current) return;
      if (type === "timeout") this._entries.delete(token);
      try { fn(); }
      catch (e) {
        if (this.diag) this.diag.error("clock-callback", { owner:entry.owner, type, error:String(e && e.stack || e) });
      }
    };
    entry.native = type === "interval" ? setInterval(invoke, delay) : setTimeout(invoke, delay);
    this._entries.set(token, entry);
    return token;
  }
  timeout(fn, ms, owner = "anonymous", onCancel = null) { return this._schedule("timeout", fn, ms, owner, onCancel); }
  interval(fn, ms, owner = "anonymous", onCancel = null) { return this._schedule("interval", fn, ms, owner, onCancel); }
  clear(token, reason = "cleared") {
    if (token == null) return false;
    const entry = this._entries.get(token);
    if (!entry) return false;
    this._entries.delete(token);
    try {
      if (entry.type === "interval") clearInterval(entry.native);
      else clearTimeout(entry.native);
    } catch (_) {}
    if (entry.onCancel) {
      try { entry.onCancel(reason); }
      catch (e) { if (this.diag) this.diag.warn("clock-cancel", { owner:entry.owner, reason, error:String(e) }); }
    }
    return true;
  }
  clearOwner(owner, reason = "owner-cleared") {
    const wanted=String(owner || "");
    let n=0;
    for (const [token,entry] of [...this._entries.entries()]) {
      if (entry.owner === wanted && this.clear(token,reason)) n++;
    }
    return n;
  }
  sleep(ms, owner = "sleep") {
    return new Promise((resolve,reject) => {
      let settled=false;
      const finish=(fn,value)=>{ if(settled)return; settled=true; fn(value); };
      const token=this.timeout(
        ()=>finish(resolve,true),
        ms,
        owner,
        reason=>finish(reject,new Error("Clock cancelled: "+String(reason||"cancelled")))
      );
      if(token===null)finish(reject,new Error("Clock destroyed"));
    });
  }
  snapshot() {
    const byOwner={}; let timeouts=0,intervals=0;
    for (const entry of this._entries.values()) {
      byOwner[entry.owner]=(byOwner[entry.owner]||0)+1;
      if(entry.type==="interval")intervals++;else timeouts++;
    }
    return {name:this.name,destroyed:this._destroyed,active:this._entries.size,timeouts,intervals,byOwner};
  }
  destroy(reason = "clock-destroy") {
    if (this._destroyed) return {cleared:0,...this.snapshot()};
    this._destroyed=true;
    let cleared=0;
    for (const token of [...this._entries.keys()]) if(this.clear(token,reason))cleared++;
    return {cleared,...this.snapshot()};
  }
}

// ===== src/01b-runtime-state.js =====
/* MasseBot 2 - runtime readiness / fail-closed state */
function MB2StartLoop(module,loop,owner){
  if(module.bot.runtime?.status==="BOOTING"){
    module._timer=module.bot.clock.timeout(loop,0,owner);
    return;
  }
  loop();
}

class MB2RuntimeState {
  constructor(events, diagnostics) {
    this.events=events; this.diag=diagnostics;
    this.status="BOOTING";
    this.phase="booting";
    this.reasons=[];
    this.details={};
    this.changedAt=Date.now();
    this._failListeners=new Set();
  }
  setPhase(phase, details=null) {
    if(this.status==="FAIL")return false;
    this.phase=String(phase||"booting");
    if(details)this.details={...this.details,...details};
    this.changedAt=Date.now();
    this.events.emit("runtime:phaseChanged",this.snapshot());
    return true;
  }
  ready(details=null) {
    if(this.status==="FAIL")return false;
    this.status="READY"; this.phase="ready";
    if(details)this.details={...this.details,...details};
    this.changedAt=Date.now();
    this.events.emit("runtime:ready",this.snapshot());
    return true;
  }
  fail(reason, details=null) {
    const r=String(reason||"runtime-fail");
    const first=this.status!=="FAIL";
    this.status="FAIL"; this.phase="failed";
    if(!this.reasons.includes(r))this.reasons.push(r);
    if(details)this.details={...this.details,[r]:details};
    this.changedAt=Date.now();
    if(first){
      this.diag&&this.diag.error("runtime:fail",{reason:r,details});
      this.events.emit("runtime:failed",{reason:r,details,snapshot:this.snapshot()});
      for(const fn of [...this._failListeners]){try{fn({reason:r,details});}catch(e){this.diag&&this.diag.warn("runtime:fail-listener",{error:String(e)});}}
    }
    return first;
  }
  onFail(fn) {
    if(typeof fn!=="function")return()=>{};
    this._failListeners.add(fn);
    if(this.status==="FAIL"){try{fn({reason:this.reasons[0]||"runtime-fail",details:this.details});}catch(_){}}
    return()=>this._failListeners.delete(fn);
  }
  allowRequest(req) {
    return this.status==="READY" || (this.status==="FAIL"&&String(req?.owner||"")==="safety");
  }
  snapshot(){return{status:this.status,phase:this.phase,reasons:this.reasons.slice(),details:{...this.details},changedAt:this.changedAt};}
}

// ===== src/02-action-coordinator.js =====
/* MasseBot 2 - ActionCoordinator */
class MB2ActionCoordinator {
  constructor(events, diagnostics) {
    this._events = events;
    this._diag = diagnostics;
    this._locks = new Map();
    this._requestGuard = null;
    this._runtimeGuard = null;
  }
  _now() { return performance && performance.now ? performance.now() : Date.now(); }
  _clean(channel) {
    const lock = this._locks.get(channel);
    if (!lock) return null;
    if (lock.expiresAt && lock.expiresAt <= this._now()) {
      this._locks.delete(channel);
      this._events.emit("action:released", { channel, owner: lock.owner, reason: "expired" });
      return null;
    }
    return lock;
  }
  setRequestGuard(fn) {
    this._requestGuard = typeof fn === "function" ? fn : null;
  }
  setRuntimeGuard(fn) {
    this._runtimeGuard = typeof fn === "function" ? fn : null;
  }
  request(channel, owner, priority = 0, ttlMs = 1000) {
    if (!channel || !owner) throw new Error("channel and owner are required");
    if(this._runtimeGuard){
      let allowed=true;
      try{allowed=this._runtimeGuard({channel,owner,priority,ttlMs})!==false;}
      catch(e){allowed=false;this._diag.warn("runtime-action-guard",{channel,owner,error:String(e)});}
      if(!allowed){
        this._events.emit("action:blocked",{channel,owner,priority,reason:"runtime-fail"});
        return false;
      }
    }
    if (this._requestGuard) {
      let allowed = true;
      try { allowed = this._requestGuard({ channel, owner, priority, ttlMs }) !== false; }
      catch (e) {
        allowed = false;
        this._diag.warn("action-guard", { channel, owner, error: String(e) });
      }
      if (!allowed) {
        this._events.emit("action:blocked", { channel, owner, priority, reason: "safety-hold" });
        return false;
      }
    }
    const now = this._now();
    const current = this._clean(channel);
    if (current && current.owner !== owner && current.priority > priority) return false;
    if (current && current.owner !== owner && current.priority === priority) return false;
    const lock = {
      channel, owner, priority,
      acquiredAt: now,
      expiresAt: ttlMs > 0 ? now + ttlMs : 0
    };
    this._locks.set(channel, lock);
    this._events.emit("action:acquired", { ...lock });
    return true;
  }
  renew(channel, owner, ttlMs = 1000) {
    const current = this._clean(channel);
    if (!current || current.owner !== owner) return false;
    current.expiresAt = ttlMs > 0 ? this._now() + ttlMs : 0;
    return true;
  }
  release(channel, owner, reason = "released") {
    const current = this._clean(channel);
    if (!current || (owner && current.owner !== owner)) return false;
    this._locks.delete(channel);
    this._events.emit("action:released", { channel, owner: current.owner, reason });
    return true;
  }
  owner(channel) {
    const lock = this._clean(channel);
    return lock ? lock.owner : null;
  }
  canAct(channel, owner) {
    const lock = this._clean(channel);
    return !lock || lock.owner === owner;
  }
  snapshot() {
    const out = {};
    [...this._locks.keys()].forEach(ch => {
      const v = this._clean(ch);
      if (v) out[ch] = { ...v };
    });
    return out;
  }
  clear(reason = "clear") {
    [...this._locks.keys()].forEach(ch => this.release(ch, null, reason));
  }
}

