  static norm(n,stable){if(n==null||typeof n!=='object')return n;if(Array.isArray(n))return n.map(x=>this.norm(x,stable));const out={};for(const [k,v]of Object.entries(n)){if(['start','end','raw'].includes(k))continue;if(n.type==='Identifier'&&k==='name')out[k]='ID';else if(n.type==='Literal'&&k==='value'&&typeof v==='string'&&!stable.has(v)&&/^[A-Za-z]{8,12}$/.test(v)&&/[a-z]/.test(v)&&/[A-Z]/.test(v))out[k]='SHUFFLED';else out[k]=this.norm(v,stable);}return out;}
  static prop(n){return n?.type==='MemberExpression'?(n.computed?n.property.value:n.property.name):null;}
