    if(n.type==='AssignmentExpression'&&this.prop(n.left?.object)==='prototype'&&n.left.object.object?.type==='Identifier'){owner=[n.left.object.object.name,this.prop(n.left)];ownerRoot=n;}
    else if(!owner.length&&n.type==='VariableDeclarator'&&n.id?.type==='Identifier'&&n.init?.type==='FunctionExpression'){owner=[n.id.name];ownerRoot=n;}
