    const text='const MB2Acorn=('+MB2AcornFactory.toString()+')();\n'+MB2ClientPackageReader.toString()+'\n'+MB2AutoResolver.toString()+'\nself.onmessage=async e=>{try{const d=e.data;const r=await MB2AutoResolver.run(JSON.parse(d.schema),d.meta,p=>self.postMessage({progress:p}));self.postMessage({result:r});}catch(e){self.postMessage({error:String(e&&e.message||e)});}};';
