/* MasseBot 2 - owned reversible hook manager with live health */
class MB2HookManager {
  constructor(events, diagnostics) {
    this.events=events; this.diag=diagnostics;
    this._records=[];
    this._criticalNames=new Set();
    this._managerId="mb2-"+Date.now()+"-"+(MB2HookManager._seq=(MB2HookManager._seq||0)+1);
  }
  setCriticalNames(names){this._criticalNames=new Set(Array.isArray(names)?names:[]);}
  _protoName(proto){try{return proto&&proto.constructor&&proto.constructor.name?String(proto.constructor.name):"prototype";}catch(_){return"prototype";}}
  wrap(proto,name,after,before,opts={}) {
    const id=String(opts.id||this._protoName(proto)+"."+name);
    const critical=opts.critical!==undefined?!!opts.critical:this._criticalNames.has(String(name));
    const record={id,name:String(name),proto,critical,status:"missing",reason:null,original:null,wrapped:null,installedAt:Date.now(),lostAt:null};
    if(!proto||typeof proto[name]!=="function"){
      record.reason="target-missing";this._records.push(record);
      this.diag&&this.diag.warn("hook:missing",{id,critical});
      return record;
    }
    const original=proto[name];
    if(original&&original.__mb2Wrapper===true){
      record.status="skipped";record.reason="existing-mb2-wrapper";record.original=original;this._records.push(record);
      this.diag&&this.diag.warn("hook:skipped",{id,critical,reason:record.reason});
      return record;
    }
    const self=this;
    function wrapped(...args){
      let ctx;
      if(before){try{ctx=before.call(this,args);}catch(e){self.diag&&self.diag.warn("hook-before",{name,error:String(e)});}}
      const result=original.apply(this,args);
      if(after){try{after.call(this,args,result,ctx);}catch(e){self.diag&&self.diag.warn("hook-after",{name,error:String(e)});}}
      return result;
    }
    Object.defineProperty(wrapped,"__mb2Wrapper",{value:true});
    Object.defineProperty(wrapped,"__mb2Original",{value:original});
    Object.defineProperty(wrapped,"__mb2HookOwner",{value:this._managerId});
    Object.defineProperty(wrapped,"__mb2HookId",{value:id});
    proto[name]=wrapped;
    record.status="installed";record.original=original;record.wrapped=wrapped;
    this._records.push(record);
    return record;
  }
  health(){
    for(const r of this._records){
      if(r.status!=="installed")continue;
      if(!r.proto||r.proto[r.name]!==r.wrapped){
        r.status="ownershipLost";r.reason="wrapper-replaced";r.lostAt=Date.now();
        this.diag&&this.diag.error("hook:ownership-lost",{id:r.id,critical:r.critical});
        this.events&&this.events.emit("runtime:hookOwnershipLost",{id:r.id,name:r.name,critical:r.critical,at:r.lostAt});
      }
    }
    return this.summary();
  }
  summary(){
    const counts={installed:0,skipped:0,missing:0,ownershipLost:0,restored:0};
    const hooks=this._records.map(r=>{if(counts[r.status]!==undefined)counts[r.status]++;return{id:r.id,name:r.name,critical:r.critical,status:r.status,reason:r.reason,lostAt:r.lostAt};});
    for(const name of this._criticalNames){
      if(hooks.some(h=>h.critical&&h.name===name))continue;
      hooks.push({id:name,name,critical:true,status:"missing",reason:"target-missing",lostAt:null});
      counts.missing++;
    }
    const criticalUnhealthy=hooks.filter(h=>h.critical&&h.status!=="installed");
    return{managerId:this._managerId,counts,total:hooks.length,criticalHealthy:criticalUnhealthy.length===0,criticalUnhealthy,hooks};
  }
  restoreAll(){
    let restored=0,skipped=0;
    for(let i=this._records.length-1;i>=0;i--){
      const r=this._records[i];
      if(r.status!=="installed"&&r.status!=="ownershipLost")continue;
      try{
        if(r.proto&&r.proto[r.name]===r.wrapped){r.proto[r.name]=r.original;r.status="restored";restored++;}
        else skipped++;
      }catch(_){skipped++;}
    }
    return{restored,skipped,summary:this.summary()};
  }
}

