/* MasseBot 2 - character scoped persistence; explicit migration, pure get() */
class MB2CharacterStorage {
  constructor(adapter, events, diagnostics, expectedCharacterName=null) {
    this.adapter=adapter;this.events=events;this.diag=diagnostics;
    const snap=adapter&&adapter.playerSnapshot?adapter.playerSnapshot():null;
    this.characterName=expectedCharacterName?String(expectedCharacterName):(snap&&snap.name?String(snap.name):null);
    this.scope=MB2CharacterStorage.scopeForName(this.characterName);
    this.prefix=`massebot2.char.v1.${this.scope}.`;
    this.sharedPrefix="massebot2.shared.v1.";
    this.migrationOwnerKey="massebot2.meta.characterMigrationOwner.v1";
    this.migrationVersionKey=`massebot2.meta.storageMigrationVersion.${this.scope}`;
    this.initialized=false;
    this.migrationSummary=null;
  }
  static scopeForName(name){const n=String(name||"").trim().toLowerCase();return n?encodeURIComponent(n):"__anonymous__";}
  _suffix(baseKey){const k=String(baseKey||"");return k.startsWith("massebot2.")?k.slice(10):k;}
  physicalKey(baseKey){return this.prefix+this._suffix(baseKey);}
  sharedPhysicalKey(baseKey){return this.sharedPrefix+this._suffix(baseKey);}
  _getRaw(key){try{return typeof localStorage!=="undefined"?localStorage.getItem(key):null;}catch(_){return null;}}
  _setRaw(key,value){try{if(typeof localStorage==="undefined")return false;localStorage.setItem(key,String(value));return true;}catch(_){return false;}}
  _removeRaw(key){try{if(typeof localStorage!=="undefined")localStorage.removeItem(key);return true;}catch(_){return false;}}
  sharedEntriesWithPrefix(basePrefix){
    const entries=[],prefix=this.sharedPhysicalKey(basePrefix);
    if(typeof localStorage==="undefined")return entries;
    for(let i=0;i<localStorage.length;i++){
      const key=localStorage.key(i);
      if(key?.startsWith(prefix))entries.push([key.slice(prefix.length),localStorage.getItem(key)]);
    }
    return entries;
  }
  sharedGet(baseKey){return this._getRaw(this.sharedPhysicalKey(baseKey));}
  sharedSet(baseKey,value){return this._setRaw(this.sharedPhysicalKey(baseKey),value);}
  sharedRemove(baseKey){return this._removeRaw(this.sharedPhysicalKey(baseKey));}
  legacyGet(baseKey){return this._getRaw(String(baseKey||""));}
  isAnonymous(){return !this.characterName||this.scope==="__anonymous__";}
  get(baseKey){if(this.isAnonymous())return null;return this._getRaw(this.physicalKey(baseKey));}
  set(baseKey,value){if(this.isAnonymous())return false;return this._setRaw(this.physicalKey(baseKey),value);}
  remove(baseKey){if(this.isAnonymous())return false;return this._removeRaw(this.physicalKey(baseKey));}
  has(baseKey){if(this.isAnonymous())return false;return this._getRaw(this.physicalKey(baseKey))!==null;}
  _claimLegacyOwner(){
    if(this.isAnonymous())return false;
    let owner=this._getRaw(this.migrationOwnerKey);
    if(!owner){owner=this.scope;this._setRaw(this.migrationOwnerKey,owner);this.diag&&this.diag.info("profile:legacy-migration-owner",{character:this.characterName,scope:this.scope});}
    return owner===this.scope;
  }
  migrateLegacyOnce(){
    const summary={claimed:false,copied:0,skipped:0,owner:this._getRaw(this.migrationOwnerKey)};
    if(this.isAnonymous())return summary;
    if(!this._claimLegacyOwner()){summary.owner=this._getRaw(this.migrationOwnerKey);return summary;}
    summary.claimed=true;summary.owner=this.scope;
    try{
      if(typeof localStorage!=="undefined"){
        const keys=[];for(let i=0;i<localStorage.length;i++)keys.push(localStorage.key(i));
        for(const key of keys){
          if(!key||!key.startsWith("massebot2."))continue;
          if(key.startsWith("massebot2.char.v1.")||key.startsWith("massebot2.shared.v1.")||key.startsWith("massebot2.meta.")||key.startsWith("massebot2.ui.v1.")){summary.skipped++;continue;}
          const dest=this.physicalKey(key);
          if(this._getRaw(dest)!==null){summary.skipped++;continue;}
          const value=this._getRaw(key);
          if(value!==null&&this._setRaw(dest,value)){summary.copied++;this.diag&&this.diag.info("profile:legacy-key-migrated",{from:key,to:dest});}
        }
      }
    }catch(e){this.diag&&this.diag.warn("profile:legacy-migration-error",{error:String(e)});}
    return summary;
  }
  migrateUiScopeOnce(){
    const summary={copied:0,source:"character-or-legacy",destination:"shared"};
    if(this.isAnonymous())return summary;
    try{
      if(typeof localStorage==="undefined")return summary;
      const candidates=[];
      for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(k)candidates.push(k);}
      const charUiPrefix=this.prefix+"ui.v1.";
      for(const key of candidates){
        let base=null;
        if(key.startsWith(charUiPrefix))base="massebot2.ui.v1."+key.slice(charUiPrefix.length);
        else if(key.startsWith("massebot2.ui.v1."))base=key;
        if(!base)continue;
        const dest=this.sharedPhysicalKey(base);
        if(this._getRaw(dest)!==null)continue;
        const value=this._getRaw(key);
        if(value!==null&&this._setRaw(dest,value))summary.copied++;
      }
    }catch(e){this.diag&&this.diag.warn("profile:ui-migration-error",{error:String(e)});}
    return summary;
  }
  initializeCharacter(){
    if(this.initialized)return this.migrationSummary;
    if(this.isAnonymous()){this.migrationSummary={ready:false,reason:"anonymous",legacy:{},ui:{}};return this.migrationSummary;}
    const legacy=this.migrateLegacyOnce();
    const ui=this.migrateUiScopeOnce();
    this._setRaw(this.migrationVersionKey,"1");
    this.initialized=true;
    this.migrationSummary={ready:true,version:1,legacy,ui};
    this.events&&this.events.emit("character:ready",{characterName:this.characterName,scope:this.scope,migration:this.migrationSummary});
    return this.migrationSummary;
  }
  scanCharacterValues(baseKey){
    const suffix=this._suffix(baseKey),prefix="massebot2.char.v1.",tail="."+suffix,out=[];
    try{if(typeof localStorage==="undefined")return out;for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);if(!key||!key.startsWith(prefix)||!key.endsWith(tail))continue;const scope=key.slice(prefix.length,key.length-tail.length);if(!scope)continue;let characterName=scope;try{characterName=decodeURIComponent(scope);}catch(_){}out.push({scope,characterName,key,value:localStorage.getItem(key)});}}catch(_){}return out;
  }
  exportShared(baseKeys=null){const out={},allow=Array.isArray(baseKeys)&&baseKeys.length?new Set(baseKeys.map(k=>this.sharedPhysicalKey(k))):null;try{if(typeof localStorage==="undefined")return out;for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(!k||!k.startsWith(this.sharedPrefix))continue;if(allow&&!allow.has(k))continue;const suffix=k.slice(this.sharedPrefix.length);out["massebot2."+suffix]=localStorage.getItem(k);}}catch(_){}return out;}
  exportProfile(){const out={};if(this.isAnonymous())return out;try{if(typeof localStorage==="undefined")return out;for(let i=0;i<localStorage.length;i++){const k=localStorage.key(i);if(!k||!k.startsWith(this.prefix))continue;const suffix=k.slice(this.prefix.length);out["massebot2."+suffix]=localStorage.getItem(k);}}catch(_){}return out;}
  importProfile(entries){if(this.isAnonymous()||!entries||typeof entries!=="object")return 0;let written=0;for(const [inputKey,value] of Object.entries(entries)){let baseKey=String(inputKey||"");if(baseKey.startsWith(this.prefix))baseKey="massebot2."+baseKey.slice(this.prefix.length);else if(baseKey.startsWith("massebot2.char.v1."))continue;if(!baseKey.startsWith("massebot2.")||baseKey.startsWith("massebot2.meta."))continue;if(this.set(baseKey,String(value)))written++;}return written;}
  snapshot(){return{characterName:this.characterName,scope:this.scope,prefix:this.prefix,sharedPrefix:this.sharedPrefix,anonymous:this.isAnonymous(),initialized:this.initialized,migration:this.migrationSummary,legacyMigrationOwner:this._getRaw(this.migrationOwnerKey),migrationVersion:this._getRaw(this.migrationVersionKey)};}
}

// ===== src/05-item-catalog.js =====
/* MasseBot 2 - ItemCatalog */
class MB2ItemCatalog {
  constructor(adapter) { this.adapter = adapter; }
  _gc() { return this.adapter.gc(); }
  byCid(cid) {const def=this._rawByCid57(cid);return def?MB2Native.view(def):null;}
  bySid(sid) {
    const gc=MB2Native.raw(this._gc());if(!gc)return null;const k=MB2Fast57(),table=gc[k.sid];
    const def=table?(table[String(sid)]||table[Number(sid)]||null):(gc[k.definitions]?.[String(sid)]||null);
    return def?MB2Native.view(def):null;
  }
  sidForCid(cid) {const gc=MB2Native.raw(this._gc()),table=gc?.[MB2Fast57().sidByCid];if(!table)return null;const v=table[Number(cid)];return v===undefined?null:Number(v);}

  foodSids() {
    // Minibia exposes the exact edible SID whitelist used by its hotbar picker.
    // Prefer that live table so MasseBot automatically follows client updates.
    try {
      if (typeof (MB2Native.type("HotbarAddModal")) !== "undefined" && (MB2Native.type("HotbarAddModal")).USABLE_FOOD_SIDS) {
        const live=Object.keys((MB2Native.type("HotbarAddModal")).USABLE_FOOD_SIDS)
          .filter(k=>(MB2Native.type("HotbarAddModal")).USABLE_FOOD_SIDS[k])
          .map(Number).filter(Number.isFinite);
        if(live.length)return new Set(live);
      }
    } catch (_) {}

    // Exact fallback copied from the current Minibia client food table.
    return new Set([
      2362,2666,2667,2668,2669,2670,2671,2672,2673,2674,
      2675,2676,2677,2678,2679,2680,2681,2682,2683,2684,
      2685,2686,2687,2688,2689,2690,2691,2695,2696,2787,
      2788,2789,2790,2791,2792,2793,2794,2795,2796,9908,
      9909,9910,9911,9921,9922,9923,9924,9925,9926,9927,
      9928,9929,9930
    ]);
  }

  isFood(ref) {
    if(!ref)return false;
    let sid=null;
    if(ref.sid!==undefined&&ref.sid!==null)sid=Number(ref.sid);
    else {
      const cid=ref.cid!==undefined?ref.cid:(ref.id!==undefined?ref.id:null);
      if(cid!==null)sid=this.sidForCid(cid);
    }
    return Number.isFinite(sid)&&this.foodSids().has(Number(sid));
  }
  properties(ref) {
    const def = typeof ref === "number" ? this.byCid(ref)
      : ref && ref.id ? this.byCid(ref.id)
      : ref && ref.cid ? this.byCid(ref.cid)
      : ref && ref.sid ? this.bySid(ref.sid) : null;
    return def && def.properties ? def.properties : {};
  }
  name(ref) {
    const props = this.properties(ref);
    return props && props.name ? String(props.name) : null;
  }
  ladderKind(ref) {
    const id=Number(ref?.id),props=this.properties(ref);
    if(id===1948||id===1968)return "use";
    if(id!==435&&!/\bladder\b/i.test(String(props.name||"")))return null;
    if(props.floorchange)return String(props.floorchange).toLowerCase()==="up"?"step-up":null;
    return "use";
  }
  findByName(name) {
    const gc = this._gc();
    if (!gc || !gc.itemDefinitionsByCid || !name) return [];
    const wanted = String(name).trim().toLowerCase();
    const out = [];
    Object.keys(gc.itemDefinitionsByCid).forEach(k => {
      const def = gc.itemDefinitionsByCid[k];
      const n = def && def.properties && def.properties.name;
      if (n && String(n).trim().toLowerCase() === wanted) out.push({ cid: Number(k), def });
    });
    return out;
  }
  searchName(text) {
    const gc = this._gc();
    if (!gc || !gc.itemDefinitionsByCid || !text) return [];
    const q = String(text).toLowerCase();
    const out = [];
    Object.keys(gc.itemDefinitionsByCid).forEach(k => {
      const def = gc.itemDefinitionsByCid[k];
      const n = def && def.properties && def.properties.name;
      if (n && String(n).toLowerCase().includes(q)) out.push({ cid: Number(k), name: n, def });
    });
    return out;
  }

_rawByCid57(cid) {const gc=MB2Native.raw(this._gc()),table=gc?.[MB2Fast57().cid];return table?.[Number(cid)]||null;}
}

// ===== src/06-world-service.js =====
/* MasseBot 2 - WorldService */
class MB2WorldService {
  constructor(adapter,items,events=null,diagnostics=null){
    this.adapter=adapter;this.items=items;this.events=events;this.diag=diagnostics;
    this.tileGen=0;this.creatureGen=0;this._offs=[];
    if(events){
      this._offs.push(events.on("world:tileTransformed",e=>this._bumpTileGen("tileTransformed",e)));
      this._offs.push(events.on("world:itemsChanged",e=>this._bumpTileGen("itemsChanged",e)));
      this._offs.push(events.on("player:teleported",e=>this._bumpTileGen("playerTeleported",e)));
      this._offs.push(events.on("creature:moved",e=>this._bumpCreatureGen("creatureMoved",e)));
      this._offs.push(events.on("creature:teleported",e=>this._bumpCreatureGen("creatureTeleported",e)));
    }
  }
  _bumpTileGen(reason,payload=null){this.tileGen++;if(this.diag)this.diag.debug("world:tile-gen",{tileGen:this.tileGen,reason,payload});return this.tileGen;}
  _bumpCreatureGen(reason,payload=null){this.creatureGen++;if(this.diag)this.diag.debug("world:creature-gen",{creatureGen:this.creatureGen,reason,payload});return this.creatureGen;}
  _gc() { return this.adapter.gc(); }
  _pos(p) {
    if (!p) return null;
    return { x: Number(p.x), y: Number(p.y), z: Number(p.z) };
  }
  playerPosition() {const p=MB2Native.raw(this._gc())?.player;return this._pos(typeof p?.getPosition==='function'?p.getPosition():null);}
  getTile(pos) {const tile=this._rawTile57(pos);return tile?MB2Native.view(tile):null;}
  getCreature(id) {
    const gc = this._gc();
    return gc && gc.world && typeof gc.world.getCreature === "function" ? gc.world.getCreature(id) : null;
  }
  isVisible(thing,mode='full') {
    const player=MB2Native.raw(this._gc())?.player;thing=MB2Native.raw(thing);if(!player||!thing)return false;
    const requested=String(mode||'full').toLowerCase();
    try{if((requested==='screen'||requested==='small')&&typeof player.canSeeSmall==='function')return !!player.canSeeSmall(thing);if(typeof player.canSee==='function')return !!player.canSee(thing);}catch(_){}
    let a=null,b=null;try{a=player.getPosition?.();}catch(_){}try{b=thing.getPosition?.();}catch(_){}
    a=this._pos(a);b=this._pos(b);if(!a||!b||a.z!==b.z)return false;const dx=Math.abs(a.x-b.x),dy=Math.abs(a.y-b.y);return requested==='screen'||requested==='small'?dx<8&&dy<6:dx<10&&dy<8;
  }

  visibleTiles(opts={}) {
    const gc=MB2Native.raw(this._gc()),player=gc?.player,world=gc?.world;if(!gc||!world||!player)return[];
    const sameFloor=opts.sameFloor!==false,visibility=String(opts.visibility||'full').toLowerCase(),requireVisible=opts.requireVisible!==false&&opts.requireCanSee!==false,me=this.playerPosition(),out=[],seen=new Set();
    const addTile=tile=>{
      tile=MB2Native.raw(tile);if(!tile)return;let pos=null;
      try{pos=typeof tile.getPosition==='function'?tile.getPosition():(tile.__position||tile.position);}catch(_){}
      pos=this._pos(pos);if(!pos||sameFloor&&me&&pos.z!==me.z)return;if(requireVisible&&!this.isVisible(tile,visibility))return;
      const key=`${pos.x},${pos.y},${pos.z}`;if(seen.has(key))return;seen.add(key);out.push({tile:opts.native57===true?tile:MB2Native.view(tile),position:pos,key});
    };
    try{const renderer=gc[MB2Fast57().renderer],groups=renderer?.getTileCache?.();if(Array.isArray(groups))for(const group of groups){const rows=group?.tiles;if(Array.isArray(rows))for(const tile of rows)addTile(tile);}}catch(_){}
    if(out.length||opts.fallbackScan===false||!me)return out;
    const small=visibility==='screen'||visibility==='small',rx=small?7:9,ry=small?5:7;
    for(let dx=-rx;dx<=rx;dx++)for(let dy=-ry;dy<=ry;dy++)addTile(this._rawTile57({x:me.x+dx,y:me.y+dy,z:me.z}));
    return out;
  }


  healthPercentage(creature) {
    const c=MB2Native.raw(creature);if(!c)return 0;
    try{const pct=Number(c.getHealthPercentage&&c.getHealthPercentage());if(Number.isFinite(pct))return Math.max(0,Math.min(100,pct));}catch(_){}
    try{const frac=Number(c.getHealthFraction&&c.getHealthFraction());if(Number.isFinite(frac))return Math.max(0,Math.min(100,frac*100));}catch(_){}
    const health=Number(c.state?.health??c.health),maxHealth=Number(c.maxHealth??c.state?.maxHealth);
    if(Number.isFinite(health)&&Number.isFinite(maxHealth)&&maxHealth>0)return Math.max(0,Math.min(100,health/maxHealth*100));
    if(Number.isFinite(health)&&health>=0&&health<=100)return health;return 100;
  }

  _sameCreature(a,b) {
    if(!a||!b)return false;
    if(a===b)return true;
    const ai=Number(a.id),bi=Number(b.id);
    return Number.isFinite(ai)&&Number.isFinite(bi)&&ai===bi;
  }

  isCombatAlive(creature) {
    const c=MB2Native.raw(creature);if(!c)return false;const gc=MB2Native.raw(this._gc()),p=gc?.player;
    const same=b=>{b=MB2Native.raw(b);if(!b)return false;if(c===b)return true;const a=Number(c.id),n=Number(b.id);return Number.isFinite(a)&&Number.isFinite(n)&&a===n;};
    try{if(same(p?.getTarget?.()))return true;}catch(_){}
    try{if(same(p?.getFollowTarget?.()))return true;}catch(_){}
    const id=Number(c.id),w=gc?.world;
    if(Number.isFinite(id)&&w){try{if(typeof w.getCreature==='function'&&w.getCreature(id))return true;}catch(_){}
      try{const a=w.activeCreatures;if(a){if(typeof a.get==='function'&&a.get(id))return true;if(a[id]||a[String(id)])return true;}}catch(_){}
    }return this.healthPercentage(c)>0;
  }

  creatures() {return this._rawCreatures57().map(c=>MB2Native.view(c));}
  visibleCreatures(small=true) {
    const p=MB2Native.raw(this._gc())?.player;if(!p)return[];const out=[];
    for(const c of this._rawCreatures57()){if(!c)continue;let visible=true;try{if(small&&typeof p.canSeeSmall==='function')visible=p.canSeeSmall(c);else if(typeof p.canSee==='function')visible=p.canSee(c);}catch(_){}
      if(visible)out.push(MB2Native.view(c));
    }return out;
  }
  isWalkable(pos) {
    const t = this.getTile(pos);
    return !!(t && typeof t.isWalkable === "function" && t.isWalkable());
  }
  isOccupied(pos) {
    const t = this.getTile(pos);
    return !t || (typeof t.isOccupied === "function" ? !!t.isOccupied() : true);
  }
  isNotPathable(pos) {
    const t = this.getTile(pos);
    return !t || (typeof t.isNotPathable === "function" ? !!t.isNotPathable() : false);
  }
  isFloorChange(pos,tile=null) {
    const t=MB2Native.raw(tile)||this._rawTile57(pos);if(!t)return false;
    const isFc=cid=>{const id=Number(cid);if(id===1948||id===1968)return true;return !!this._definition57(id)?.properties?.floorchange;};
    try{if(isFc(t.id))return true;}catch(_){}for(const it of t.items||[])try{if(it&&isFc(it.id))return true;}catch(_){}return false;
  }

  standInfo(pos,tile57=null) {
    const p=this._pos(pos),tile=p?(MB2Native.raw(tile57)||this._rawTile57(p)):null;
    if(!p||!tile)return Object.freeze({position:p,loaded:false,walkable:false,occupied:false,pathable:false,floorChange:false,usable:false,blocksShot:true,tileGen:this.tileGen});
    let walkable=false,occupied=true,pathable=false;const k=MB2Fast57();
    try{walkable=typeof tile.isWalkable==='function'&&!!tile.isWalkable();if(!walkable)walkable=typeof tile.__hasWalkableGroundItem==='function'&&!!tile.__hasWalkableGroundItem();}catch(_){}
    try{occupied=typeof tile[k.occupied]==='function'?!!tile[k.occupied]():true;}catch(_){}
    try{pathable=typeof tile.isNotPathable==='function'?!tile.isNotPathable():walkable;}catch(_){pathable=false;}
    const info={position:p,loaded:true,walkable,occupied,pathable,floorChange:this.isFloorChange(p,tile),usable:this.isUsable(p,tile),blocksShot:this._tileBlocksProjectile(tile),tileGen:this.tileGen};
    return Object.freeze(this.fields?this.fields.stand(p,info,tile):info);
  }

  isUsable(pos,tile=null) {
    const gc=MB2Native.raw(this._gc()),t=MB2Native.raw(tile)||this._rawTile57(pos);if(!gc||!t)return false;
    try{if(typeof gc.mouse?.__isUsableTile==='function')return !!gc.mouse.__isUsableTile(t);}catch(_){}
    const top=typeof t.peekItem==='function'?t.peekItem(0xFF):null;if(!top)return false;
    const id=top.id,p=this._definition57(id)?.properties;if(p&&(p.type==='door'||p.type==='rune'||p.floorchange))return true;
    return !!(gc.usableItemCids&&gc.usableItemCids.has(id));
  }
  _itemBlocksProjectile(item) {
    item=MB2Native.raw(item);if(!item)return false;
    try{const flags=MB2Native.type('PropBitFlag')?.prototype?.flags;if(flags&&item.hasFlag&&item.hasFlag(flags.DatFlagBlockProjectile))return true;}catch(_){}
    const def=this._definition57(item.id);return !!(def&&(Number(def.flags)&2)===2);
  }
  _tileBlocksProjectile(tile) {
    tile=MB2Native.raw(tile);if(!tile)return true;const def=this._definition57(tile.id);if(def&&(Number(def.flags)&2)===2)return true;
    const rows=tile.items||[];for(let i=0;i<rows.length;i++)if(this._itemBlocksProjectile(rows[i]))return true;return false;
  }
  traceLine(from, to) {
    from = this._pos(from); to = this._pos(to);
    if (!from || !to || from.z !== to.z) return [];
    let x0 = from.x, y0 = from.y, x1 = to.x, y1 = to.y;
    const points = [];
    const dx = Math.abs(x1 - x0), sx = x0 < x1 ? 1 : -1;
    const dy = -Math.abs(y1 - y0), sy = y0 < y1 ? 1 : -1;
    let err = dx + dy;
    while (true) {
      points.push({ x: x0, y: y0, z: from.z });
      if (x0 === x1 && y0 === y1) break;
      const e2 = 2 * err;
      if (e2 >= dy) { err += dy; x0 += sx; }
      if (e2 <= dx) { err += dx; y0 += sy; }
    }
    return points;
  }
  isShootable(from, to) {
    const line = this.traceLine(from, to);
    if (line.length < 2) return false;
    for (let i = 1; i < line.length - 1; i++) {
      const tile = this.getTile(line[i]);
      if (this._tileBlocksProjectile(tile)) return false;
    }
    return true;
  }
  snapshot() {
    const gc = this._gc(), p = gc && gc.player;
    return {
      position:this.playerPosition(),
      creatures:this.creatures().length,
      visibleCreatures:this.visibleCreatures().length,
      targetId:p&&p.getTarget&&p.getTarget()?p.getTarget().id:null,
      tileGen:this.tileGen,
      creatureGen:this.creatureGen
    };
  }
  destroy(){this._offs.forEach(f=>{try{f();}catch(_){}});this._offs=[];}

_rawCreatures57() {const active=MB2Native.raw(this._gc())?.world?.activeCreatures;return active?Object.values(active):[];}

_definition57(cid) {return this.items._rawByCid57?this.items._rawByCid57(cid):MB2Native.raw(this.items.byCid(cid));}

_rawTile57(pos) {const world=MB2Native.raw(this._gc())?.world;return typeof world?.getTileFromWorldPosition==='function'?world.getTileFromWorldPosition(this.adapter.position(pos)):null;}
}

// ===== src/06a-world-frame.js =====
/* MasseBot 2 - immutable decision frame source */
class MB2FrameService {
  constructor(adapter,world,coordinator,events,diagnostics){
    this.adapter=adapter;this.world=world;this.coordinator=coordinator;this.events=events;this.diag=diagnostics;this._seq=0;this._last=null;this._movement=null;this._lastSignature=null;this._lastMono=0;this.reuseWindowMs=20;
  }
  setMovement(movement){this._movement=movement||null;}
  _key(p){return p?`${Number(p.x)},${Number(p.y)},${Number(p.z)}`:"";}
  capture(reason="tick"){
    const player=this.adapter.playerSnapshot();
    const motion=this.adapter.playerMotionState();
    const pp=player&&player.position;
    const signature=[pp&&pp.x,pp&&pp.y,pp&&pp.z,motion.moving?1:0,Number(motion.preWalks||motion.pendingPredictedSteps)||0,motion.predictionFrozen?1:0,player&&player.targetId,player&&player.followId,this.world.tileGen,this.world.creatureGen].join("|");
    const mono=typeof performance!=="undefined"&&performance.now?performance.now():Date.now();
    if(this._last&&this._lastSignature===signature&&mono-this._lastMono<=this.reuseWindowMs)return this._last;
    const tiles=new Map();
    for(const row of this.world.visibleTiles({sameFloor:true,visibility:"full",requireVisible:true,fallbackScan:true,native57:true})){
      const info=this.world.standInfo(row.position,row.tile);tiles.set(row.key,info);
    }
    const creatures=new Map();
    for(const c of (this.world._rawCreatures57?this.world._rawCreatures57():this.world.creatures())){
      if(!c)continue;let pos=null;try{pos=c.getPosition?this.adapter.plainPosition(c.getPosition()):null;}catch(_){}
      const hpRaw=this.world.healthPercentage(c);
      let hpDisplay=Number.isFinite(Number(hpRaw))?Number(hpRaw):null;
      if(!c.getHealthPercentage&&!c.getHealthFraction&&!(c.state&&Number.isFinite(Number(c.state.health)))&&!Number.isFinite(Number(c.health)))hpDisplay=null;
      const info=Object.freeze({id:Number(c.id),name:c.name==null?null:String(c.name),type:c.type,pos,hpDisplay,alive:this.world.isCombatAlive(c),visibleScreen:this.world.isVisible(c,"screen"),visibleFull:this.world.isVisible(c,"full")});
      creatures.set(Number(c.id),info);
    }
    const frame=Object.freeze({
      seq:++this._seq,at:Date.now(),reason:String(reason||"tick"),tileGen:this.world.tileGen,creatureGen:this.world.creatureGen,
      me:Object.freeze({position:player&&player.position?Object.freeze({...player.position}):null,positionConfirmed:!!motion.confirmed,z:player&&player.position?Number(player.position.z):null,moving:!!motion.moving,preWalks:Number(motion.preWalks||motion.pendingPredictedSteps)||0,predictionFrozen:!!motion.predictionFrozen,serverWalkConfirmation:motion.serverWalkConfirmation}),
      viewport:"full",tiles,creatures,targetId:player&&player.targetId!=null?Number(player.targetId):null,followId:player&&player.followId!=null?Number(player.followId):null,
      movement:Object.freeze({owner:this.coordinator.owner("movement"),handoffSeq:this._movement&&typeof this._movement.handoffSequence==="function"?this._movement.handoffSequence():0})
    });
    this._last=frame;this._lastSignature=signature;this._lastMono=typeof performance!=="undefined"&&performance.now?performance.now():Date.now();return frame;
  }
  current(){return this._last||this.capture("current");}
  key(pos){return this._key(pos);}
  stand(frame,pos){return frame&&frame.tiles?frame.tiles.get(this._key(pos))||null:null;}
  creature(frame,id){return frame&&frame.creatures?frame.creatures.get(Number(id))||null:null;}
  isShootable(frame,from,to){
    const line=this.world.traceLine(from,to);if(line.length<2)return false;
    for(let i=1;i<line.length-1;i++){const info=this.stand(frame,line[i]);if(!info||!info.loaded||info.blocksShot)return false;}
    return true;
  }
  snapshot(){const f=this._last;return f?{seq:f.seq,at:f.at,tileGen:f.tileGen,creatureGen:f.creatureGen,position:f.me.position,positionConfirmed:f.me.positionConfirmed,preWalks:f.me.preWalks,movement:f.movement,tiles:f.tiles.size,creatures:f.creatures.size,targetId:f.targetId}:null;}
}

// ===== src/07-inventory-service.js =====
/* MasseBot 2 - InventoryService */
class MB2InventoryService {
  constructor(adapter, items, events, diagnostics, clock) {
    this.adapter = adapter;
    this.items = items;
    this.events = events;
    this.diag = diagnostics;
    this.clock = clock;
    this._destroyed = false;
    this._countQueue = [];
    this._activeCount = null;
    this._exactCountQueue = [];
    this._activeExactCount = null;
    this._exactCountCache = new Map();
    this._listQueue = [];
    this._activeList = null;
    this._offCount = events.on("inventory:countResult", r => this._handleCountResult(r));
    this._offExactCount = events.on("inventory:hotbarCount", r => this._handleExactCountResult(r));
    this._offList = events.on("inventory:listResult", r => this._handleListResult(r));
  }
  _gc() { return this.adapter.gc(); }
  containers() {
    const gc = this._gc();
    if (!gc || !gc.player) return [];
    const out = [];
    if (gc.player.equipment) out.push(gc.player.equipment);
    if (gc.player.__openedContainers) gc.player.__openedContainers.forEach(c => {if(!this.adapter.depot?.isDepotContainer(c,true))out.push(c);});
    return out;
  }
  _fluidName(item) {
    if(!item)return null;
    try{
      if(typeof item.getFluidName==="function"){
        const n=item.getFluidName();
        if(n)return String(n).trim().toLowerCase();
      }
    }catch(_){}
    const fluid=Number(item.fluidType)||0;
    const known={7:"mana fluid",10:"life fluid"};
    return known[fluid]||null;
  }

  semanticName(item) {
    const fluid=this._fluidName(item);
    if(fluid)return fluid;
    const base=this.items.name(item);
    return base?String(base).trim().toLowerCase():null;
  }

  scanOpen() {
    const out = [];
    this.containers().forEach(container => {
      if (!container || !container.slots) return;
      for (let i = 0; i < container.slots.length; i++) {
        const item = container.getSlotItem ? container.getSlotItem(i) : (container.slots[i] && container.slots[i].item);
        if (!item) continue;
        const baseName=this.items.name(item)||null;
        const fluidName=this._fluidName(item);
        const explicitSid=item.sid ? Number(item.sid) : null;
        out.push({
          container, slot: i, item,
          cid: Number(item.id),
          explicitSid,
          sid: explicitSid || this.items.sidForCid(item.id),
          count: typeof item.getCount === "function" ? item.getCount() : (item.count || 1),
          fluidType: Number(item.fluidType)||0,
          name: baseName,
          fluidName,
          semanticName: fluidName || (baseName ? String(baseName).trim().toLowerCase() : null)
        });
      }
    });
    return out;
  }
  findOpenByName(name) {
    const q = String(name || "").trim().toLowerCase();
    return this.scanOpen().filter(x =>
      String(x.semanticName||"").toLowerCase()===q ||
      String(x.name||"").toLowerCase()===q ||
      String(x.fluidName||"").toLowerCase()===q
    );
  }

  countOpenByName(name) {
    return this.findOpenByName(name).reduce((sum,x)=>sum+Math.max(0,Number(x.count)||0),0);
  }
  findOpenByCid(cid) { return this.scanOpen().filter(x => x.cid === Number(cid)); }
  countOpenByCid(cid) { return this.findOpenByCid(cid).reduce((a, x) => a + (Number(x.count) || 0), 0); }
  findOpenBySid(sid, opts = {}) {
    const wanted=Number(sid);
    return this.scanOpen().filter(x=>{
      if(opts.explicitOnly===true)return Number(x.explicitSid)===wanted;
      return Number(x.sid)===wanted;
    });
  }

  useOpenAt(ref, pos, opts = {}) {
    const gc=this._gc();
    if(!gc||!gc.world)throw new Error("world unavailable");
    if(!ref||!ref.container)throw new Error("open inventory ref required");
    const targetPos=this.adapter.position(pos);
    const targetTile=gc.world.getTileFromWorldPosition
      ? gc.world.getTileFromWorldPosition(targetPos)
      : null;
    if(!targetTile)throw new Error("target tile unavailable");

    const from={which:ref.container,index:Number(ref.slot)};
    const to={which:targetTile,index:0xFF};

    // Prefer Minibia's own use-with path. It contains item-specific client
    // behavior (notably Fishing Rod CID 3483 being ranged and therefore NOT
    // auto-walking toward shallow/walkable water).
    if(opts.nativeClient!==false&&gc.mouse&&typeof gc.mouse.__handleItemUseWith==="function"){
      gc.mouse.__handleItemUseWith(from,to);
      return true;
    }

    if(typeof (MB2Native.type("ItemUseWithPacket"))==="undefined")throw new Error("ItemUseWithPacket unavailable");
    gc.send(new (MB2Native.type("ItemUseWithPacket"))(from,to));
    return true;
  }

  countOpenExact(cid, fluidType = 0) {
    const wanted=Number(cid), fluid=Math.max(0,Number(fluidType)||0);
    return this.scanOpen()
      .filter(x=>Number(x.cid)===wanted&&Number(x.fluidType||0)===fluid)
      .reduce((sum,x)=>sum+Math.max(0,Number(x.count)||0),0);
  }

  _exactKey(cid,fluidType=0) {
    return Number(cid)+":"+Math.max(0,Number(fluidType)||0);
  }

  _settleQuery(q, mode, value) {
    if(!q||q.settled)return false;
    q.settled=true;
    if(q.timer){try{this.clock.clear(q.timer,"inventory-query-settled");}catch(_){}q.timer=null;}
    try{
      if(mode==="resolve")q.resolve(value);
      else q.reject(value instanceof Error?value:new Error(String(value||"Inventory query failed")));
    }catch(_){}
    return true;
  }

  exactCountReading(cid,fluidType=0,maxAgeMs=Infinity) {
    const reading=this._exactCountCache.get(this._exactKey(cid,fluidType))||null;
    if(!reading)return null;
    if(Number.isFinite(Number(maxAgeMs))&&Date.now()-Number(reading.at||0)>Number(maxAgeMs))return null;
    return {...reading};
  }

  exactCountSnapshot() {
    return Array.from(this._exactCountCache.values()).map(x=>({...x}));
  }
  listFullDistinct(opts = {}) {
    if(this._destroyed)return Promise.reject(new Error("Inventory is closed"));
    return new Promise((resolve,reject)=>{
      this._listQueue.push({
        timeoutMs:Math.max(500,Number(opts.timeoutMs)||2500),
        resolve,reject,settled:false,timer:null
      });
      this._drainListQueue();
    });
  }

  _drainListQueue() {
    if(this._activeList||!this._listQueue.length)return;
    const gc=this._gc();
    if(!gc||typeof (MB2Native.type("InventoryListQueryPacket"))==="undefined"){
      const q=this._listQueue.shift();
      this._settleQuery(q,"reject",new Error("INVENTORY_LIST_QUERY capability unavailable"));
      return this._drainListQueue();
    }
    const q=this._listQueue.shift();
    this._activeList=q;
    q.timer=this.clock.timeout(()=>{
      if(this._activeList!==q)return;
      this._activeList=null;
      this._settleQuery(q,"reject",new Error("INVENTORY_LIST_QUERY timeout"));
      this._drainListQueue();
    },q.timeoutMs,"inventory:list-query");
    try{
      gc.send(new (MB2Native.type("InventoryListQueryPacket"))());
    }catch(e){
      this._activeList=null;
      this._settleQuery(q,"reject",e);
      this._drainListQueue();
    }
  }

  _handleListResult(result) {
    const q=this._activeList;
    if(!q||!result||!Array.isArray(result.items))return;
    this._activeList=null;
    this._settleQuery(q,"resolve",{
      items:result.items.map(x=>({
        cid:Number(x.cid),
        sid:Number(x.sid),
        fluidType:Number(x.fluidType)||0,
        tintId:Number(x.tintId)||0
      }))
    });
    this._drainListQueue();
  }

  foodOpenCandidates() {
    return this.scanOpen().filter(x=>this.items.isFood(x));
  }

  async foodFullCandidates(opts = {}) {
    const list=await this.listFullDistinct(opts);
    return (list.items||[]).filter(x=>this.items.isFood(x));
  }

  countSids(sids, opts = {}) {
    if(this._destroyed)return Promise.reject(new Error("Inventory is closed"));
    const list = [...new Set((Array.isArray(sids) ? sids : [sids]).map(Number).filter(Number.isFinite))].slice(0, 50);
    if (!list.length) return Promise.resolve({});
    return new Promise((resolve, reject) => {
      this._countQueue.push({ sids: list, timeoutMs: Math.max(500, Number(opts.timeoutMs) || 3000), resolve, reject, settled:false, timer:null });
      this._drainCountQueue();
    });
  }
  _drainCountQueue() {
    if (this._activeCount || !this._countQueue.length) return;
    const gc = this._gc();
    if (!gc || typeof (MB2Native.type("ItemCountQueryPacket")) === "undefined") {
      const q = this._countQueue.shift();
      this._settleQuery(q,"reject",new Error("ITEM_COUNT_QUERY capability unavailable"));
      return this._drainCountQueue();
    }
    const q = this._countQueue.shift();
    this._activeCount = q;
    q.timer = this.clock.timeout(() => {
      if (this._activeCount !== q) return;
      this._activeCount = null;
      this._settleQuery(q,"reject",new Error("ITEM_COUNT_QUERY timeout"));
      this._drainCountQueue();
    }, q.timeoutMs,"inventory:count-query");
    try {
      gc.send(new (MB2Native.type("ItemCountQueryPacket"))(q.sids));
    } catch (e) {
      this._activeCount = null;
      this._settleQuery(q,"reject",e);
      this._drainCountQueue();
    }
  }
  _handleCountResult(result) {
    const q = this._activeCount;
    if (!q || !result || !Array.isArray(result.items)) return;
    const map = {};
    for(const item of result.items){
      const count=MB2KnownStat(item?.count);
      if(Number.isSafeInteger(count))map[Number(item.sid)]=count;
    }
    const complete = q.sids.every(sid => Object.prototype.hasOwnProperty.call(map, sid));
    if (!complete) return; // likely another UI query
    this._activeCount = null;
    this._settleQuery(q,"resolve",map);
    this._drainCountQueue();
  }
  countExact(cid, fluidType = 0, opts = {}) {
    if(this._destroyed)return Promise.reject(new Error("Inventory is closed"));
    const id=Number(cid), fluid=Math.max(0,Number(fluidType)||0);
    if(!Number.isFinite(id)||id<=0)return Promise.reject(new Error("Invalid exact-count CID"));
    return new Promise((resolve,reject)=>{
      this._exactCountQueue.push({
        cid:id,
        fluidType:fluid,
        timeoutMs:Math.max(500,Number(opts.timeoutMs)||3000),
        resolve,reject,settled:false,timer:null
      });
      this._drainExactCountQueue();
    });
  }

  _drainExactCountQueue() {
    if(this._activeExactCount||!this._exactCountQueue.length)return;
    const gc=this._gc();
    if(!gc||typeof (MB2Native.type("HotbarCountsRequestPacket"))==="undefined"){
      const q=this._exactCountQueue.shift();
      this._settleQuery(q,"reject",new Error("HOTBAR_COUNTS_REQUEST capability unavailable"));
      return this._drainExactCountQueue();
    }
    const q=this._exactCountQueue.shift();
    this._activeExactCount=q;
    q.timer=this.clock.timeout(()=>{
      if(this._activeExactCount!==q)return;
      this._activeExactCount=null;
      this._settleQuery(q,"reject",new Error("HOTBAR_COUNTS_REQUEST timeout"));
      this._drainExactCountQueue();
    },q.timeoutMs,"inventory:exact-count-query");
    try{
      // Prevent a solicited refresh from being misread by Minibia's local
      // "Using one of N..." supply-message detector.
      const nm=gc.networkManager;
      if(nm){
        if(!nm.__supplySeedExpect)nm.__supplySeedExpect={};
        nm.__supplySeedExpect[q.cid+":"+q.fluidType]=Date.now()+q.timeoutMs+500;
      }
      gc.send(new (MB2Native.type("HotbarCountsRequestPacket"))([{id:q.cid,fluidType:q.fluidType}]));
    }catch(e){
      this._activeExactCount=null;
      this._settleQuery(q,"reject",e);
      this._drainExactCountQueue();
    }
  }

  _handleExactCountResult(result) {
    if(!result)return;
    const cid=Number(result.cid),fluidType=Math.max(0,Number(result.fluidType)||0);
    if(!Number.isFinite(cid)||cid<=0)return;
    const count=MB2KnownStat(result.count);
    if(!Number.isSafeInteger(count))return;
    const at=Number(result.at)||Date.now();

    // IMPORTANT: HOTBAR_ITEM_COUNT is also sent unsolicited by Minibia when an
    // item count changes (including rune production). Keep EVERY update.
    // The previous implementation threw these away unless countExact() was
    // actively waiting, which could leave RuneMaker stuck on an old low count.
    const reading={cid,fluidType,count,at};
    this._exactCountCache.set(this._exactKey(cid,fluidType),reading);
    this.events.emit("inventory:exactCountChanged",{...reading});

    const q=this._activeExactCount;
    if(!q)return;
    if(cid!==q.cid||fluidType!==q.fluidType)return;

    this._activeExactCount=null;
    this._settleQuery(q,"resolve",count);
    this._drainExactCountQueue();
  }

  _sendHotbar(cid, fluidType, mode, targetCreatureId, pos) {
    const gc = this._gc();
    if (!gc || typeof (MB2Native.type("HotbarUsePacket")) === "undefined") throw new Error("HotbarUsePacket unavailable");
    gc.send(new (MB2Native.type("HotbarUsePacket"))(Number(cid), Number(fluidType) || 0, Number(mode), Number(targetCreatureId) || 0, pos ? this.adapter.position(pos) : undefined));
    return true;
  }
  useByCid(cid, fluidType = 0) { return this._sendHotbar(cid, fluidType, 0, 0); }
  useByCidOnSelf(cid, fluidType = 0) { return this._sendHotbar(cid, fluidType, 2, 0); }
  useByCidOnCreature(cid, creatureId, fluidType = 0) { return this._sendHotbar(cid, fluidType, 1, creatureId); }
  useByCidAt(cid, pos, fluidType = 0) { return this._sendHotbar(cid, fluidType, 3, 0, pos); }
  useOpenOnCreature(ref, creatureId) {
    const gc = this._gc();
    if (!gc || typeof (MB2Native.type("ItemUseOnCreaturePacket")) === "undefined") throw new Error("ItemUseOnCreaturePacket unavailable");
    if (!ref || !ref.container) throw new Error("open inventory ref required");
    gc.send(new (MB2Native.type("ItemUseOnCreaturePacket"))({ which: ref.container, index: ref.slot }, Number(creatureId)));
    return true;
  }
  findOpenSourcesByCid(cid, fluidType = 0, opts = {}) {
    const gc=this._gc();
    const eq=gc&&gc.player&&gc.player.equipment;
    const wanted=Number(cid), fluid=Math.max(0,Number(fluidType)||0);
    const excluded=new Set((opts.excludeEquipmentSlots||[]).map(Number));
    return this.scanOpen().filter(x=>{
      if(Number(x.cid)!==wanted)return false;
      if(fluid>0&&Number(x.fluidType||0)!==fluid)return false;
      const isEq=!!(eq&&x.container===eq);
      if(isEq&&opts.includeEquipment===false)return false;
      if(isEq&&excluded.has(Number(x.slot)))return false;
      return true;
    }).sort((a,b)=>{
      const ae=eq&&a.container===eq,be=eq&&b.container===eq;
      if(ae!==be)return ae?1:-1;
      return (Number(b.count)||0)-(Number(a.count)||0);
    });
  }

  moveOpenToEquipmentExact(cid, slotIndex, fluidType = 0, requestedCount = 1) {
    if(this.adapter.depot?.state.active)return null;
    const gc=this._gc(),eq=gc&&gc.player&&gc.player.equipment;
    if(!eq||typeof (MB2Native.type("ItemMovePacket"))==="undefined")return null;
    const slot=Number(slotIndex);
    const source=this.findOpenSourcesByCid(cid,fluidType,{
      includeEquipment:true,
      excludeEquipmentSlots:[slot]
    })[0];
    if(!source)return null;
    const available=Math.max(0,Math.floor(Number(source.count)||0));
    const count=Math.min(255,available,Math.max(0,Math.floor(Number(requestedCount)||0)));
    if(count<=0)return null;
    gc.send(new (MB2Native.type("ItemMovePacket"))(
      {which:source.container,index:Number(source.slot)},
      {which:eq,index:slot},
      count
    ));
    return{
      sent:true,count,
      sourceKind:source.container===eq?"equipment":"backpack",
      sourceSlot:Number(source.slot),
      sourceContainerId:source.container&&source.container.__containerId
    };
  }

  move(ref, toContainer, toSlot, count) {
    if(this.adapter.depot?.state.active)return null;
    const gc = this._gc();
    if (!gc || typeof (MB2Native.type("ItemMovePacket")) === "undefined") throw new Error("ItemMovePacket unavailable");
    if (!ref || !ref.container || !toContainer) throw new Error("source and destination required");
    const n = count == null ? (Number(ref.count) || 1) : Number(count);
    gc.send(new (MB2Native.type("ItemMovePacket"))({ which: ref.container, index: ref.slot }, { which: toContainer, index: Number(toSlot) }, n));
    return true;
  }
  moveToTile(ref, tile, count) {
    if(this.adapter.depot?.state.active)return null;
    const gc=this._gc();
    if(!gc||typeof (MB2Native.type("ItemMovePacket"))==="undefined")throw new Error("ItemMovePacket unavailable");
    if(!ref||!ref.container||!tile)throw new Error("source and ground tile required");
    const available=Math.max(1,Number(ref.count)||1);
    const n=Math.max(1,Math.min(255,Math.floor(count==null?available:Number(count)||1)));
    gc.send(new (MB2Native.type("ItemMovePacket"))(
      {which:ref.container,index:Number(ref.slot)},
      {which:tile,index:0xFF},
      n
    ));
    return n;
  }

  destroy() {
    if(this._destroyed)return false;
    this._destroyed=true;
    if (this._offCount) this._offCount(); this._offCount=null;
    if (this._offExactCount) this._offExactCount(); this._offExactCount=null;
    if (this._offList) this._offList(); this._offList=null;

    const err=()=>new Error("InventoryService destroyed");
    if(this._activeCount)this._settleQuery(this._activeCount,"reject",err());
    if(this._activeExactCount)this._settleQuery(this._activeExactCount,"reject",err());
    if(this._activeList)this._settleQuery(this._activeList,"reject",err());
    this._activeCount=null;
    this._activeExactCount=null;
    this._activeList=null;

    while(this._countQueue.length)this._settleQuery(this._countQueue.shift(),"reject",err());
    while(this._exactCountQueue.length)this._settleQuery(this._exactCountQueue.shift(),"reject",err());
    while(this._listQueue.length)this._settleQuery(this._listQueue.shift(),"reject",err());
    this._exactCountCache.clear();
    return true;
  }
}

