        const plan=this.plan(from,r.goal);
        if(!plan.needed||!plan.path.length){this.cancel(plan.needed?"route-blocked":"field-section-ended");return;}
        this._remember(r,plan,from,tileGen);
        next=r.path[0];direction=this._readyStep(from,next);
