    this._pending=null;this._open=null;this._bodies=[];this._blocked=new WeakMap();this._bodyWindows=new WeakMap();this._recentOpens=[];this._selected=null;this._holdUntil=0;this._timer=null;this._client=bot.adapter.gc();this._player=this._client?.player;
    try{this._merge(JSON.parse(bot.storage.get(this.key)||"{}"));}catch(_){}
    this._offs=[bot.events.on("loot:corpseHandled",e=>{if(this.config.enabled&&e.body)this._bodies.push({...e,at:Date.now(),attempted:false});this._bodies=this._bodies.slice(-12);}),bot.events.on("inventory:containerOpened",p=>this._opened(p))];
