        if(!this.bot.coordinator.request("item-move","item-loot",8,3500))return;
        const sig=this._sig(it),p={source,dest,sig,fingerprint,count:slot.count,sourceCount:this._total(source,sig),destCount:this._total(dest,sig),at:now};
        // Set before send: synchronous fixture/client receipts are valid too.
        this._pending=p;this.state.pendingMove={sid:Number(it.sid),cid:Number(it.id),count:slot.count,at:now};
        try{if(!this.bot.inventory.move({container:source,slot:i,count:this._count(it)},dest,slot.index,slot.count)){this._pending=null;this.state.pendingMove=null;return;}}
        catch(error){this._pending=null;this.state.pendingMove=null;this.bot.coordinator.release("item-move","item-loot","error");throw error;}
        if(now<this._holdUntil)this._hold();this._status("Flyttar "+(this.bot.items.name(it)||"föremål"));return;
